export const FEE_MODES = ['none', 'fixed_order', 'fixed_ticket', 'percentage'];

export function calculatePricing(unitPriceMinor, quantity, fee = { mode: 'none' }) {
  if (!Number.isInteger(unitPriceMinor) || unitPriceMinor < 0) throw new Error('Invalid unit price');
  if (!Number.isInteger(quantity) || quantity < 1) throw new Error('Invalid quantity');
  const subtotalMinor = unitPriceMinor * quantity;
  let feeTotalMinor = 0;
  switch (fee.mode) {
    case 'none': break;
    case 'fixed_order': feeTotalMinor = integer(fee.fixedMinor); break;
    case 'fixed_ticket': feeTotalMinor = integer(fee.fixedMinor) * quantity; break;
    case 'percentage': feeTotalMinor = Math.floor((subtotalMinor * integer(fee.bps) + 5000) / 10000); break;
    default: throw new Error('Unknown fee mode');
  }
  return { subtotalMinor, feeTotalMinor, totalMinor: subtotalMinor + feeTotalMinor };
}

function integer(value) {
  if (!Number.isInteger(value) || value < 0) throw new Error('Invalid fee configuration');
  return value;
}

export function feeLabel(fee) {
  if (!fee || fee.mode === 'none') return 'No booking fee';
  if (fee.mode === 'percentage') return `${fee.bps / 100}% booking fee`;
  if (fee.mode === 'fixed_ticket') return 'Booking fee per ticket';
  return 'Booking fee per order';
}
