function clone(value) { return JSON.parse(JSON.stringify(value)); }

function load() {
  try {
    const value = JSON.parse(localStorage.getItem(STORAGE_KEY));
    if (value?.version === 4) return value.data;
  } catch { /* reset corrupt demo state */ }
  const value = clone(seed);
  save(value);
  return value;
}

function save(data) { localStorage.setItem(STORAGE_KEY, JSON.stringify({ version: 4, data })); }

function id(prefix) {
  const bytes = crypto.getRandomValues(new Uint8Array(10));
  return `${prefix}-${Array.from(bytes, (value) => value.toString(16).padStart(2, '0')).join('')}`;
}

function code(length = 8) {
  const alphabet = '23456789ABCDEFGHJKMNPQRSTUVWXYZ';
  const bytes = crypto.getRandomValues(new Uint8Array(length));
  return Array.from(bytes, (value) => alphabet[value % alphabet.length]).join('');
}

function normalizeEmail(email) { return String(email).trim().toLowerCase(); }

function activeHeld(data, tierId, exceptOrderId = null) {
  const now = Date.now();
  return data.holds
    .filter((hold) => hold.tierId === tierId && hold.status === 'active' && Date.parse(hold.expiresAt) > now && hold.orderId !== exceptOrderId)
    .reduce((sum, hold) => sum + hold.quantity, 0);
}

function decorateEvent(data, event) {
  return {
    ...clone(event),
    tiers: event.tiers.map((tier) => ({
      ...clone(tier),
      remaining: Math.max(0, tier.capacity - tier.sold - activeHeld(data, tier.id)),
    })),
  };
}

export const mockStore = {
  reset() { const data = clone(seed); save(data); return data; },

  listEvents() {
    const data = load();
    return data.events.filter((event) => event.status === 'published').map((event) => decorateEvent(data, event));
  },

  getEvent(slug) {
    const data = load();
    const event = data.events.find((item) => item.slug === slug && item.status === 'published');
    return event ? decorateEvent(data, event) : null;
  },

  initiateOrder(input) {
    const data = load();
    const event = data.events.find((item) => item.slug === input.eventSlug && item.status === 'published');
    if (!event) throw problem('event_not_found', 'This event is no longer available.');
    const tier = event.tiers.find((item) => item.id === input.tierId && item.status === 'active');
    if (!tier) throw problem('tier_not_found', 'That ticket tier is no longer available.');
    if (!Number.isInteger(input.quantity) || input.quantity < 1 || input.quantity > tier.maxPerOrder) {
      throw problem('invalid_quantity', `Choose between 1 and ${tier.maxPerOrder} tickets.`);
    }
    if (!Array.isArray(input.attendees) || input.attendees.length !== input.quantity) {
      throw problem('attendee_mismatch', 'Add one attendee for every ticket.');
    }
    if (!input.termsAccepted) throw problem('terms_required', 'Accept the ticket terms before paying.');

    const existing = data.orders.find((item) => item.idempotencyKey === input.idempotencyKey);
    if (existing) return initiationResponse(existing);

    const remaining = tier.capacity - tier.sold - activeHeld(data, tier.id);
    if (remaining < input.quantity) throw problem('sold_out', remaining ? `Only ${remaining} ${tier.name} ticket${remaining === 1 ? '' : 's'} remain.` : `${tier.name} is sold out.`);

    const pricing = calculatePricing(tier.priceMinor, input.quantity, event.fee);
    const orderId = id('ord');
    const token = `${code(24)}${code(24)}`;
    const now = new Date();
    const expiresAt = new Date(now.getTime() + 15 * 60 * 1000).toISOString();
    const displayReference = `TXR-2026-${code(6)}`;
    const providerReference = `pay_${code(18)}`;
    const buyer = {
      id: id('buy'), fullName: input.buyer.fullName.trim(), email: normalizeEmail(input.buyer.email), phone: input.buyer.phone.trim(),
    };
    data.buyers.push(buyer);
    const order = {
      id: orderId, displayReference, statusToken: token, idempotencyKey: input.idempotencyKey,
      eventId: event.id, eventSlug: event.slug, tierId: tier.id, buyerId: buyer.id, buyer,
      quantity: input.quantity, attendees: input.attendees.map((attendee, index) => ({
        id: id('att'), position: index + 1, fullName: attendee.fullName.trim(), email: normalizeEmail(attendee.email),
      })),
      pricing, feeSnapshot: clone(event.fee), unitPriceMinor: tier.priceMinor,
      providerReference, paymentStatus: 'pending', fulfillmentStatus: 'held', emailStatus: 'not_queued',
      paymentMethod: null, createdAt: now.toISOString(), holdExpiresAt: expiresAt, paidAt: null, fulfilledAt: null,
    };
    data.orders.push(order);
    data.holds.push({ id: id('hold'), orderId, tierId: tier.id, quantity: input.quantity, status: 'active', expiresAt, createdAt: now.toISOString() });
    save(data);
    return initiationResponse(order);
  },

  completePayment(statusToken, paymentMethod = 'card') {
    const data = load();
    const order = data.orders.find((item) => item.statusToken === statusToken);
    if (!order) throw problem('order_not_found', 'We could not find that order.');
    if (order.fulfillmentStatus === 'fulfilled') return clone(order);
    const event = data.events.find((item) => item.id === order.eventId);
    const tier = event.tiers.find((item) => item.id === order.tierId);
    const hold = data.holds.find((item) => item.orderId === order.id);
    const holdActive = hold?.status === 'active' && Date.parse(hold.expiresAt) > Date.now();
    const remaining = tier.capacity - tier.sold - activeHeld(data, tier.id, order.id);
    order.paymentStatus = 'paid';
    order.paymentMethod = paymentMethod;
    order.paidAt = new Date().toISOString();
    data.paymentEvents.push({ id: id('pye'), orderId: order.id, type: 'charge.success', verified: true, receivedAt: new Date().toISOString() });

    if (!holdActive && remaining < order.quantity) {
      if (hold) hold.status = 'expired';
      order.fulfillmentStatus = 'paid_exception';
      order.exceptionReason = 'late_payment_no_capacity';
      save(data);
      return clone(order);
    }

    if (hold) { hold.status = 'consumed'; hold.consumedAt = new Date().toISOString(); }
    tier.sold += order.quantity;
    order.attendees.forEach((attendee) => {
      const random = code(8);
      const ticketNumber = `${event.code}-${tier.code}-${random.slice(0, 4)}-${random.slice(4)}`;
      const signature = `demo-v1-${code(12).toLowerCase()}`;
      data.tickets.push({
        id: id('tkt'), orderId: order.id, attendeeId: attendee.id, eventId: event.id, tierId: tier.id,
        number: ticketNumber, signature, qrPayload: `TIX1|${ticketNumber}|${signature}`,
        attendeeName: attendee.fullName, attendeeEmail: attendee.email, status: 'issued',
        issuedAt: new Date().toISOString(), checkedInAt: null,
      });
    });
    order.fulfillmentStatus = 'fulfilled';
    order.fulfilledAt = new Date().toISOString();
    order.emailStatus = 'sent';
    order.attendees.forEach((attendee) => data.emailDeliveries.push({
      id: id('mail'), orderId: order.id, recipient: attendee.email, role: 'attendee', status: 'sent', sentAt: new Date().toISOString(),
    }));
    data.emailDeliveries.push({ id: id('mail'), orderId: order.id, recipient: order.buyer.email, role: 'purchaser', status: 'sent', sentAt: new Date().toISOString() });
    save(data);
    return clone(order);
  },

  getOrder(statusToken) {
    const data = load();
    const order = data.orders.find((item) => item.statusToken === statusToken);
    if (!order) return null;
    const event = data.events.find((item) => item.id === order.eventId);
    const tier = event?.tiers.find((item) => item.id === order.tierId);
    const tickets = data.tickets.filter((item) => item.orderId === order.id && item.status !== 'void');
    return { ...clone(order), event: clone(event), tier: clone(tier), tickets: clone(tickets) };
  },

  resend(statusToken, recipient) {
    const data = load();
    const order = data.orders.find((item) => item.statusToken === statusToken);
    const normalized = normalizeEmail(recipient);
    if (!order || (order.buyer.email !== normalized && !order.attendees.some((attendee) => attendee.email === normalized))) {
      throw problem('not_authorized', 'That email is not attached to this order.');
    }
    data.emailDeliveries.push({ id: id('mail'), orderId: order.id, recipient: normalized, role: order.buyer.email === normalized ? 'purchaser' : 'attendee', status: 'sent', sentAt: new Date().toISOString(), resend: true });
    save(data);
    return { sent: true };
  },

  resolveException(orderId, resolution = 'refunded') {
    const data = load();
    const order = data.orders.find((item) => item.id === orderId && item.fulfillmentStatus === 'paid_exception');
    if (!order) throw problem('not_found', 'That exception is no longer open.');
    if (resolution !== 'refunded') throw problem('invalid_resolution', 'The sandbox records manual refunds only.');
    order.paymentStatus = 'refunded';
    order.fulfillmentStatus = 'voided';
    order.exceptionReason = null;
    order.resolvedAt = new Date().toISOString();
    save(data);
    return clone(order);
  },

  adminData() {
    const data = load();
    const orders = data.orders.map((order) => {
      const event = data.events.find((item) => item.id === order.eventId);
      const tier = event?.tiers.find((item) => item.id === order.tierId);
      return { ...clone(order), eventName: event?.name, tierName: tier?.name };
    });
    const paidOrders = orders.filter((order) => order.paymentStatus === 'paid');
    const seededRevenue = 184650000;
    return {
      events: data.events.map((event) => decorateEvent(data, event)), orders,
      tickets: clone(data.tickets), staff: clone(data.staff), deliveries: clone(data.emailDeliveries),
      metrics: {
        revenueMinor: seededRevenue + paidOrders.reduce((sum, order) => sum + order.pricing.totalMinor, 0),
        sold: data.events.flatMap((event) => event.tiers).reduce((sum, tier) => sum + tier.sold, 0),
        checkedIn: data.tickets.filter((ticket) => ticket.status === 'checked_in').length,
        exceptions: orders.filter((order) => order.fulfillmentStatus === 'paid_exception').length,
      },
    };
  },

  createEvent(input) {
    const data = load();
    const eventId = id('evt');
    const eventCode = (input.code || code(5)).toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 10);
    const event = {
      id: eventId, slug: `${input.name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')}-${code(3).toLowerCase()}`,
      code: eventCode, name: input.name.trim(), eyebrow: input.eyebrow || 'Live event / Lagos', description: input.description || 'Event details will be added before publication.',
      venue: input.venue.trim(), startsAt: input.startsAt, doors: input.doors || 'Door time to be confirmed', image: input.image || '/posters/lagos-after-dark.jpg',
      accent: input.accent || '#E45A2A', status: input.status || 'draft', supportEmail: input.supportEmail || 'hello@tixora.demo', fee: input.fee || { mode: 'none' }, tiers: [],
    };
    if (input.tier?.name) event.tiers.push({
      id: id('tier'), code: (input.tier.code || 'REG').toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 10),
      name: input.tier.name.trim(), description: input.tier.description || 'General admission', priceMinor: input.tier.priceMinor,
      capacity: input.tier.capacity, sold: 0, maxPerOrder: input.tier.maxPerOrder || 6, status: 'active',
    });
    data.events.push(event); save(data); return decorateEvent(data, event);
  },

  updateEvent(eventId, patch) {
    const data = load();
    const event = data.events.find((item) => item.id === eventId);
    if (!event) throw problem('not_found', 'Event not found.');
    Object.assign(event, patch);
    save(data);
    return decorateEvent(data, event);
  },

  saveTiers(eventId, tiers) {
    const data = load(); const event = data.events.find((item) => item.id === eventId);
    if (!event) throw problem('not_found', 'Event not found.');
    event.tiers = tiers.map((tier, index) => {
      const existing = event.tiers.find((item) => item.id === tier.id);
      const capacity = Number(tier.capacity);
      if (existing && capacity < existing.sold) throw problem('capacity_too_low', `${existing.name} already has ${existing.sold} sold tickets.`);
      return { ...existing, id: tier.id || id('tier'), code: tier.code.toUpperCase(), name: tier.name.trim(), description: tier.description || '', priceMinor: Number(tier.priceMinor), capacity, sold: existing?.sold || 0, maxPerOrder: Number(tier.maxPerOrder), displayOrder: index, status: tier.status || 'active' };
    });
    save(data); return decorateEvent(data, event);
  },

  inviteStaff(input) {
    const data = load();
    if (data.staff.some((item) => item.email.toLowerCase() === input.email.toLowerCase())) throw problem('duplicate_staff', 'That email already belongs to a staff member.');
    const staff = { id: id('staff'), name: input.name.trim(), email: input.email.toLowerCase(), events: input.eventIds, status: 'active' };
    data.staff.push(staff); save(data); return clone(staff);
  },

  replaceTicket(ticketId, mode, reason) {
    const data = load(); const ticket = data.tickets.find((item) => item.id === ticketId);
    if (!ticket || ticket.status === 'void') throw problem('ticket_not_found', 'That ticket is no longer active.');
    ticket.status = 'void'; ticket.voidedAt = new Date().toISOString(); ticket.voidReason = reason;
    let replacement = null;
    if (mode === 'reissue') {
      const event = data.events.find((item) => item.id === ticket.eventId); const tier = event.tiers.find((item) => item.id === ticket.tierId); const random = code(8); const number = `${event.code}-${tier.code}-${random.slice(0, 4)}-${random.slice(4)}`; const signature = `demo-v1-${code(12).toLowerCase()}`;
      replacement = { ...ticket, id: id('tkt'), number, signature, qrPayload: `TIX1|${number}|${signature}`, status: 'issued', issuedAt: new Date().toISOString(), checkedInAt: null, voidedAt: null, voidReason: null };
      data.tickets.push(replacement);
      data.emailDeliveries.push({ id: id('mail'), orderId: ticket.orderId, ticketId: replacement.id, recipient: replacement.attendeeEmail, role: 'attendee', status: 'sent', sentAt: new Date().toISOString(), reissue: true });
    }
    save(data); return { old: clone(ticket), replacement: clone(replacement) };
  },

  checkIn({ eventId, value, staffName = 'Demo staff' }) {
    const data = load();
    const cleaned = String(value).trim();
    const ticketNumber = cleaned.startsWith('TIX1|') ? cleaned.split('|')[1] : cleaned.toUpperCase();
    const suppliedSignature = cleaned.startsWith('TIX1|') ? cleaned.split('|')[2] : null;
    const ticket = data.tickets.find((item) => item.number === ticketNumber);
    if (!ticket) return { valid: false, reason: 'ticket_not_found' };
    if (suppliedSignature && suppliedSignature !== ticket.signature) return { valid: false, reason: 'invalid_signature' };
    if (ticket.eventId !== eventId) return { valid: false, reason: 'wrong_event' };
    if (ticket.status === 'void') return { valid: false, reason: 'ticket_void' };
    if (ticket.status === 'checked_in') return { valid: false, reason: 'already_checked_in', checkedInAt: ticket.checkedInAt, attendeeName: ticket.attendeeName };
    ticket.status = 'checked_in';
    ticket.checkedInAt = new Date().toISOString();
    ticket.checkedInBy = staffName;
    const event = data.events.find((item) => item.id === ticket.eventId);
    const tier = event.tiers.find((item) => item.id === ticket.tierId);
    save(data);
    return { valid: true, ticketNumber: ticket.number, attendeeName: ticket.attendeeName, tier: tier.name, checkedInAt: ticket.checkedInAt };
  },
};

function initiationResponse(order) {
  return {
    orderId: order.id, orderReference: order.displayReference, authorizationUrl: 'demo://paystack',
    holdExpiresAt: order.holdExpiresAt, statusAccessToken: order.statusToken, pricing: clone(order.pricing),
  };
}

function problem(code, message) {
  const error = new Error(message);
  error.code = code;
  return error;
}
