export const LAGOS_TZ = 'Africa/Lagos';

export function money(minor = 0, { compact = false } = {}) {
  const value = Number(minor) / 100;
  if (compact && value >= 1_000_000) return `₦${(value / 1_000_000).toFixed(value % 1_000_000 ? 1 : 0)}m`;
  return new Intl.NumberFormat('en-NG', {
    style: 'currency', currency: 'NGN', maximumFractionDigits: value % 1 ? 2 : 0,
  }).format(value).replace('NGN', '₦');
}

export function dateParts(iso) {
  const date = new Date(iso);
  const month = new Intl.DateTimeFormat('en-NG', { month: 'short', timeZone: LAGOS_TZ }).format(date).toUpperCase();
  const day = new Intl.DateTimeFormat('en-NG', { day: '2-digit', timeZone: LAGOS_TZ }).format(date);
  const weekday = new Intl.DateTimeFormat('en-NG', { weekday: 'long', timeZone: LAGOS_TZ }).format(date);
  const year = new Intl.DateTimeFormat('en-NG', { year: 'numeric', timeZone: LAGOS_TZ }).format(date);
  const time = new Intl.DateTimeFormat('en-NG', { hour: 'numeric', minute: '2-digit', timeZone: LAGOS_TZ }).format(date);
  return { month, day, weekday, year, time };
}

export function longDate(iso) {
  return new Intl.DateTimeFormat('en-NG', {
    weekday: 'long', day: 'numeric', month: 'long', year: 'numeric',
    hour: 'numeric', minute: '2-digit', timeZone: LAGOS_TZ,
  }).format(new Date(iso));
}

export function shortDate(iso) {
  return new Intl.DateTimeFormat('en-NG', {
    day: 'numeric', month: 'short', year: 'numeric', timeZone: LAGOS_TZ,
  }).format(new Date(iso));
}

export function relativeCount(count, singular, plural = `${singular}s`) {
  return `${count.toLocaleString('en-NG')} ${count === 1 ? singular : plural}`;
}

export function initials(name = '') {
  return name.split(/\s+/).filter(Boolean).slice(0, 2).map((part) => part[0]).join('').toUpperCase();
}

export function escapeHtml(value = '') {
  const node = document.createElement('div');
  node.textContent = String(value);
  return node.innerHTML;
}

export function secondsLeft(iso) {
  return Math.max(0, Math.floor((new Date(iso).getTime() - Date.now()) / 1000));
}

export function clock(totalSeconds) {
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;
  return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
}
