import { mockStore } from './mock-store.js';
import { supabase, bearerHeaders } from './supabase.js';

const mode = import.meta.env.VITE_API_MODE || 'mock';
const base = import.meta.env.VITE_API_BASE_URL || '';
const anonKey = import.meta.env.VITE_SUPABASE_ANON_KEY || '';
const wait = (ms = 180) => new Promise((resolve) => setTimeout(resolve, ms));

async function request(path, options = {}) {
  const response = await fetch(`${base}${path}`, {
    ...options,
    headers: {
      'content-type': 'application/json',
      ...(anonKey ? { apikey: anonKey, authorization: `Bearer ${anonKey}` } : {}),
      ...(options.headers || {}),
    },
  });
  const body = await response.json().catch(() => ({}));
  if (!response.ok) {
    const error = new Error(body.message || 'Something went wrong.');
    error.code = body.code || 'request_failed';
    throw error;
  }
  return body;
}

const mock = {
  async listEvents() { await wait(); return mockStore.listEvents(); },
  async getEvent(slug) { await wait(); return mockStore.getEvent(slug); },
  async listScanEvents() { await wait(); return mockStore.listEvents(); },
  async initiateOrder(input) { await wait(450); return mockStore.initiateOrder(input); },
  async completeDemoPayment(token, method) { await wait(900); return mockStore.completePayment(token, method); },
  async getOrder(token) { await wait(300); return mockStore.getOrder(token); },
  async resend(token, email) { await wait(400); return mockStore.resend(token, email); },
  async adminData() { await wait(); return mockStore.adminData(); },
  async createEvent(input) { await wait(400); return mockStore.createEvent(input); },
  async updateEvent(id, patch) { await wait(350); return mockStore.updateEvent(id, patch); },
  async saveTiers(id, tiers) { await wait(400); return mockStore.saveTiers(id, tiers); },
  async inviteStaff(input) { await wait(400); return mockStore.inviteStaff(input); },
  async replaceTicket(id, mode, reason) { await wait(400); return mockStore.replaceTicket(id, mode, reason); },
  async resolveException(id) { await wait(350); return mockStore.resolveException(id, 'refunded'); },
  async checkIn(input) { await wait(450); return mockStore.checkIn(input); },
  reset() { return mockStore.reset(); },
};

const live = {
  listEvents: () => request('/functions/v1/public-events'),
  getEvent: (slug) => request(`/functions/v1/event-detail?slug=${encodeURIComponent(slug)}`),
  async listScanEvents() { return request('/functions/v1/staff-events', { headers: await bearerHeaders() }); },
  initiateOrder: (input) => request('/functions/v1/initiate-order', { method: 'POST', body: JSON.stringify(input) }),
  getOrder: (token) => request('/functions/v1/order-status', { method: 'POST', headers: { authorization: `Bearer ${token}` }, body: '{}' }),
  resend: (token, email) => request('/functions/v1/resend-tickets', { method: 'POST', headers: { authorization: `Bearer ${token}` }, body: JSON.stringify({ email }) }),
  async checkIn(input) { return request('/functions/v1/check-in-scan', { method: 'POST', headers: await bearerHeaders(), body: JSON.stringify(input) }); },
  async adminData() {
    const payload = await request('/functions/v1/admin-api?section=overview', { headers: await bearerHeaders() });
    return normalizeAdmin(payload);
  },
  async createEvent(input) {
    return request('/functions/v1/admin-api', { method: 'PATCH', headers: await bearerHeaders(), body: JSON.stringify({ action: 'create_event', input }) });
  },
  async updateEvent(id, patch) {
    const mapped = { name: patch.name, venue: patch.venue, accent_color: patch.accent, status: patch.status, starts_at: patch.startsAt };
    if (patch.fee) Object.assign(mapped, { fee_mode: patch.fee.mode, fee_fixed_minor: patch.fee.fixedMinor ?? null, fee_bps: patch.fee.bps ?? null });
    return request('/functions/v1/admin-api', { method: 'PATCH', headers: await bearerHeaders(), body: JSON.stringify({ action: 'update_event', eventId: id, patch: mapped }) });
  },
  async saveTiers(id, tiers) {
    return request('/functions/v1/admin-api', { method: 'PATCH', headers: await bearerHeaders(), body: JSON.stringify({ action: 'save_tiers', eventId: id, tiers }) });
  },
  async inviteStaff(input) {
    return request('/functions/v1/admin-api', { method: 'PATCH', headers: await bearerHeaders(), body: JSON.stringify({ action: 'invite_staff', input }) });
  },
  async replaceTicket(id, mode, reason) {
    return request('/functions/v1/admin-api', { method: 'PATCH', headers: await bearerHeaders(), body: JSON.stringify({ action: 'replace_ticket', ticketId: id, mode, reason }) });
  },
  async resolveException(id) {
    return request('/functions/v1/admin-api', { method: 'PATCH', headers: await bearerHeaders(), body: JSON.stringify({ action: 'resolve_paid_exception', orderId: id, resolution: 'refunded' }) });
  },
  async getSession() { return (await supabase?.auth.getSession())?.data?.session || null; },
  async signIn(email, password) {
    if (!supabase) throw new Error('Supabase is not configured.');
    const { data, error } = await supabase.auth.signInWithPassword({ email, password });
    if (error) throw error; return data.session;
  },
  async signOut() { await supabase?.auth.signOut(); },
};

function normalizeAdmin(payload) {
  const events = (payload.events || []).map((event) => ({
    id: event.id, slug: event.slug, code: event.event_code, name: event.name, venue: event.venue,
    startsAt: event.starts_at, image: event.cover_image_path ? `/posters/${event.cover_image_path}` : '', accent: event.accent_color,
    status: event.status, fee: { mode: event.fee_mode, fixedMinor: event.fee_fixed_minor == null ? undefined : Number(event.fee_fixed_minor), bps: event.fee_bps ?? undefined },
    tiers: (event.ticket_tiers || []).map((tier) => ({ id: tier.id, name: tier.name, priceMinor: Number(tier.unit_price_minor), capacity: tier.capacity, sold: tier.tickets_sold, remaining: tier.capacity - tier.tickets_sold })),
  }));
  const orders = (payload.orders || []).map((order) => ({
    id: order.id, displayReference: order.display_reference, eventId: order.event_id, tierId: order.tier_id,
    eventName: order.events?.name, tierName: order.ticket_tiers?.name, quantity: order.quantity,
    buyer: { fullName: order.buyers?.full_name, email: order.buyers?.email, phone: order.buyers?.phone },
    attendees: (order.attendees || []).map((person) => ({ id: person.id, position: person.position, fullName: person.full_name, email: person.email })), pricing: { subtotalMinor: Number(order.subtotal_minor), feeTotalMinor: Number(order.fee_total_minor), totalMinor: Number(order.total_minor) },
    unitPriceMinor: Number(order.unit_price_minor), paymentStatus: order.payment_status, fulfillmentStatus: order.fulfillment_status,
    createdAt: order.created_at,
  }));
  const tickets = (payload.tickets || []).map((ticket) => ({
    id: ticket.id, eventId: ticket.event_id, tierId: ticket.tier_id, number: ticket.ticket_number,
    attendeeName: ticket.attendees?.full_name, attendeeEmail: ticket.attendees?.email,
    status: ticket.status, issuedAt: ticket.issued_at, checkedInAt: ticket.checked_in_at,
  }));
  return { events, orders, tickets, staff: payload.staff || [], deliveries: payload.deliveries || [], metrics: {
    revenueMinor: Number(payload.metrics?.revenueMinor || 0), sold: payload.metrics?.sold || 0,
    checkedIn: payload.metrics?.checkedIn || 0, exceptions: payload.metrics?.exceptions || 0,
  } };
}

export const api = mode === 'mock' ? mock : live;
export const isMockMode = mode === 'mock';
